import 'package:flutter/material.dart';
import '../theme/app_colors.dart';
class SectionTitle extends StatelessWidget { final String title; final String? action; final VoidCallback? onAction; const SectionTitle({super.key,required this.title,this.action,this.onAction}); @override Widget build(BuildContext context)=>Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(title,style:const TextStyle(fontSize:17,fontWeight:FontWeight.w800)),if(action!=null) TextButton(onPressed:onAction,child:Text(action!,style:const TextStyle(color:AppColors.primary,fontWeight:FontWeight.w700)))]); }
